function buildVariants(d: DemoDef): ProductVariant[] {
  return d.sizes.map((size, i) => {
    const [own, sup] = d.stock[i % d.stock.length];
    return {
      id: `${d.slug}-${size}`,
      sku: `DEMO-${d.slug.replace("demo-", "").toUpperCase().slice(0, 14)}-${size}`,
      size,
      color: d.color,
      colorHex: d.colorHex,
      price: null,
      availability: {
        status: statusFromQuantities(own, sup),
        ownQuantity: own,
        supplierQuantity: sup,
        leadTimeDays: sup > 0 ? 5 : null,
        supplierConfirmedAt: sup > 0 ? "2026-11-01T15:00:00.000Z" : null,
      },
    };
  });
}

export const demoProducts: Product[] = defs.map((d, idx) => ({
  id: `demo-${idx + 1}`,
  slug: d.slug,
  name: d.name,
  reference: `DEMO-${String(idx + 1).padStart(3, "0")}`,
  brand: demoBrands[d.brand],
  category: categories.find((c) => c.slug === d.category)!,
  gender: d.gender,
  shoeType: d.shoeType,
  description: d.description,
  materials: "Información de materiales disponible cuando se cargue el producto real.",
  price: d.price,
  compareAtPrice: d.compareAt ?? null,
  isNew: Boolean(d.isNew),
  isActive: true,
  isDemo: true,
  images: [
    { url: `/demo/${d.slug}.webp`, alt: `${d.name} — render conceptual de demostración`, position: 0 },
    { url: `/demo/${d.slug}-top.webp`, alt: `${d.name} — vista superior (demostración)`, position: 1 },
  ],
  modelUrl: null,
  conceptColorway: d.colorway,
  variants: buildVariants(d),
  createdAt: new Date(Date.UTC(2026, 9, 1 + idx)).toISOString(),
}));

